DROP VIEW IF EXISTS eatlq.phase2_surface_status;
DROP VIEW IF EXISTS eatlq.phase2_raw_status;

CREATE VIEW eatlq.phase2_raw_status
AS
SELECT
    count() AS raw_rows,
    max(received_at_ms) AS latest_received_at_ms,
    intDiv(toInt64(toUnixTimestamp64Milli(now64(3)) - toUnixTimestamp64Milli(max(received_at_ms))), 1000) AS raw_lag_seconds
FROM eatlq.raw_evm_logs;

CREATE VIEW eatlq.phase2_surface_status
AS
SELECT
    'erc20_transfers' AS surface,
    'token' AS venue_type,
    toUInt16(30) AS recent_window_minutes,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef') AS raw_total_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66) AS raw_projectable_total_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66) AS raw_projectable_unique_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef')) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66)) AS raw_unprojectable_total_rows,
    (SELECT count() FROM eatlq.erc20_transfers) AS normalized_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef')) - toInt64((SELECT count() FROM eatlq.erc20_transfers)) AS total_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66)) AS raw_projectable_duplicate_total_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66)) - toInt64((SELECT count() FROM eatlq.erc20_transfers)) AS projectable_total_gap,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_recent_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_recent_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_unique_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_unprojectable_recent_rows,
    (SELECT count() FROM eatlq.erc20_transfers WHERE received_at_ms >= now() - INTERVAL 30 MINUTE) AS normalized_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.erc20_transfers WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS recent_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_projectable_duplicate_recent_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 66 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.erc20_transfers WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS projectable_recent_gap,
    toUInt64(coalesce((SELECT sum(duplicate_rows - 1) FROM eatlq.erc20_transfers_deduped WHERE duplicate_rows > 1), 0)) AS duplicate_surplus,
    (SELECT uniqExact(token_address) - uniqExactIf(token_address, has_registry_match = 1) FROM eatlq.erc20_transfers_enriched) AS uncovered_registry_gap,
    (SELECT max(block_time) FROM eatlq.erc20_transfers) AS latest_block_time,
    (SELECT max(latest_ingested_at) FROM eatlq.erc20_transfers_deduped) AS latest_ingested_at

UNION ALL

SELECT
    'uniswap_v2_swaps' AS surface,
    'pair' AS venue_type,
    toUInt16(30) AS recent_window_minutes,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b')) AS raw_total_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258) AS raw_projectable_total_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258) AS raw_projectable_unique_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b'))) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258)) AS raw_unprojectable_total_rows,
    (SELECT count() FROM eatlq.uniswap_v2_swaps) AS normalized_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b'))) - toInt64((SELECT count() FROM eatlq.uniswap_v2_swaps)) AS total_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258)) AS raw_projectable_duplicate_total_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_swaps)) AS projectable_total_gap,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_recent_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_recent_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_unique_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_unprojectable_recent_rows,
    (SELECT count() FROM eatlq.uniswap_v2_swaps WHERE received_at_ms >= now() - INTERVAL 30 MINUTE) AS normalized_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_swaps WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS recent_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_projectable_duplicate_recent_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xb3e2773606abfd36b5bd91394b3a54d1398336c65005baf7bf7a05efeffaf75b') AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 258 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_swaps WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS projectable_recent_gap,
    toUInt64(coalesce((SELECT sum(duplicate_rows - 1) FROM eatlq.uniswap_v2_swaps_deduped WHERE duplicate_rows > 1), 0)) AS duplicate_surplus,
    (SELECT uniqExact(pair_address) - uniqExactIf(pair_address, has_registry_match = 1) FROM eatlq.uniswap_v2_swaps_enriched) AS uncovered_registry_gap,
    (SELECT max(block_time) FROM eatlq.uniswap_v2_swaps) AS latest_block_time,
    (SELECT max(latest_ingested_at) FROM eatlq.uniswap_v2_swaps_deduped) AS latest_ingested_at

UNION ALL

SELECT
    'uniswap_v2_mints' AS surface,
    'pair' AS venue_type,
    toUInt16(30) AS recent_window_minutes,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f') AS raw_total_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130) AS raw_projectable_total_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130) AS raw_projectable_unique_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f')) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130)) AS raw_unprojectable_total_rows,
    (SELECT count() FROM eatlq.uniswap_v2_mints) AS normalized_total_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f')) - toInt64((SELECT count() FROM eatlq.uniswap_v2_mints)) AS total_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130)) AS raw_projectable_duplicate_total_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_mints)) AS projectable_total_gap,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_recent_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_recent_rows,
    (SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE) AS raw_projectable_unique_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_unprojectable_recent_rows,
    (SELECT count() FROM eatlq.uniswap_v2_mints WHERE received_at_ms >= now() - INTERVAL 30 MINUTE) AS normalized_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_mints WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS recent_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_projectable_duplicate_recent_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x4c209b5fc8ad50758f13e2e1088ba56a560dff690a1c6fef26394f4c03821c4f' AND length(topic1) = 66 AND length(data) >= 130 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v2_mints WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS projectable_recent_gap,
    toUInt64(coalesce((SELECT sum(duplicate_rows - 1) FROM eatlq.uniswap_v2_mints_deduped WHERE duplicate_rows > 1), 0)) AS duplicate_surplus,
    (SELECT uniqExact(pair_address) - uniqExactIf(pair_address, has_registry_match = 1) FROM eatlq.uniswap_v2_mints_enriched) AS uncovered_registry_gap,
    (SELECT max(block_time) FROM eatlq.uniswap_v2_mints) AS latest_block_time,
    (SELECT max(latest_ingested_at) FROM eatlq.uniswap_v2_mints_deduped) AS latest_ingested_at

UNION ALL

SELECT
    'uniswap_v2_burns' AS surface,
    'pair' AS venue_type,
    toUInt16(30) AS recent_window_minutes,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xdccd412f0b1252819cb1fd330b93224ca42612892bb3f4f789976e6d81936496') AS raw_total_rows,
    (SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0xdccd412f0b1252819cb1fd330b93224ca42612892bb3f4f789976e6d81936496' AND length(topic1) = 66 AND length(topic2) = 66 AND length(data) >= 130) AS raw_projectable_total_rows,
