    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND length(topic1) = 66 AND length(topic2) = 66 AND length(topic3) = 66 AND length(data) >= 194 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_unprojectable_recent_rows,
    (SELECT count() FROM eatlq.uniswap_v3_burns WHERE received_at_ms >= now() - INTERVAL 30 MINUTE) AS normalized_recent_rows,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v3_burns WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS recent_gap,
    toInt64((SELECT count() FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND length(topic1) = 66 AND length(topic2) = 66 AND length(topic3) = 66 AND length(data) >= 194 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND length(topic1) = 66 AND length(topic2) = 66 AND length(topic3) = 66 AND length(data) >= 194 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) AS raw_projectable_duplicate_recent_rows,
    toInt64((SELECT uniqExact(tuple(chain_id, lower(address), tx_hash, log_index)) FROM eatlq.raw_evm_logs WHERE topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c' AND length(topic1) = 66 AND length(topic2) = 66 AND length(topic3) = 66 AND length(data) >= 194 AND received_at_ms >= now() - INTERVAL 30 MINUTE)) - toInt64((SELECT count() FROM eatlq.uniswap_v3_burns WHERE received_at_ms >= now() - INTERVAL 30 MINUTE)) AS projectable_recent_gap,
    toUInt64(coalesce((SELECT sum(duplicate_rows - 1) FROM eatlq.uniswap_v3_burns_deduped WHERE duplicate_rows > 1), 0)) AS duplicate_surplus,
    (SELECT uniqExact(pool_address) - uniqExactIf(pool_address, has_registry_match = 1) FROM eatlq.uniswap_v3_burns_enriched) AS uncovered_registry_gap,
    (SELECT max(block_time) FROM eatlq.uniswap_v3_burns) AS latest_block_time,
    (SELECT max(latest_ingested_at) FROM eatlq.uniswap_v3_burns_deduped) AS latest_ingested_at;
